-- ============================================================
-- SEED EXT 2: Módulo 05 — Future Simple (exercícios 71-180)
-- Novos tópicos: time clauses + will, future passive, will vs
-- may/might, shall (formal), academic future, TOEFL produção
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'future-simple';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo future-simple não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: future time clauses (when/as soon as/once/until + present simple)
  (cid,11,71,'gap_fill','___ (when) she ___ (finish) the analysis, she will submit the paper.','When / finishes',NULL,'Future time clauses: when + present simple (NOT will), main clause = will.','hard'),
  (cid,11,72,'multiple_choice','Which sentence is CORRECT?','As soon as the results are ready, the team will publish them.','["As soon as the results will be ready, the team will publish them.","As soon as the results are ready, the team will publish them.","When the results will be ready, the team publishes them.","Once the results will arrive, the team will publish them."]','Time conjunctions (when/as soon as/once/until) + present simple, not will.','hard'),
  (cid,11,73,'gap_fill','I won''t start the experiment until all participants ___ (sign) the consent forms.','have signed / sign',NULL,'"Until + present simple/present perfect" for negative future time clause.','hard'),
  (cid,11,74,'gap_fill','Once the committee ___ (approve) the budget, the project will commence immediately.','approves',NULL,'"Once + present simple" = future time clause. Main clause: will + base verb.','medium'),
  (cid,11,75,'multiple_choice','Choose the correct time clause: "The professor ___ the grades ___ all papers ___ submitted."','won''t release / until / have been','["won''t release / when / were submitted","won''t release / until / have been submitted","will release / as soon as / will be submitted","releases / once / are submitting"]','Won''t release until + present perfect passive (have been submitted).','hard'),
  (cid,11,76,'gap_fill','After the funding ___ (secure/passive), the research team will be assembled.','has been secured / is secured',NULL,'Time clause with passive: after + present perfect passive or present simple passive.','hard'),
  (cid,11,77,'multiple_choice','A student asks: "Will you help me when I need it?" The teacher responds correctly:','Of course — I''ll help you whenever you need it.','["Of course — I will help you whenever you will need it.","Of course — I''ll help you whenever you need it.","Of course — I help you whenever you need it.","Of course — I will help you whenever you needed it."]','Whenever + present simple; main clause = will.','medium'),

  -- BLOCK 12: future passive (will be + past participle)
  (cid,12,78,'gap_fill','The data ___ (analyze/passive) by an independent team next month.','will be analyzed',NULL,'Future passive: will + be + past participle.','medium'),
  (cid,12,79,'multiple_choice','Choose the correct future passive:','The new campus will be inaugurated in 2026.','["The new campus will inaugurate in 2026 (active — campus can''t inaugurate itself).","The new campus is going to inaugurate in 2026.","The new campus will be inaugurated in 2026.","The new campus will be inaugurate in 2026."]','Will + be + past participle for future passive.','medium'),
  (cid,12,80,'gap_fill','All applications ___ (review/passive) by the selection committee before the end of the month.','will be reviewed',NULL,'Future passive: will be + past participle.','easy'),
  (cid,12,81,'multiple_choice','Identify the correct negative future passive: "Results ___ until the peer-review process is complete."','won''t be released','["will not released","won''t release","won''t be released","won''t be releasing"]','Won''t be + past participle = negative future passive.','medium'),
  (cid,12,82,'gap_fill','The grant proposal ___ (evaluate/passive) using three independent criteria.','will be evaluated',NULL,'Will be + past participle.','easy'),
  (cid,12,83,'multiple_choice','Why is future passive preferred in academic writing?','To focus on the process/object rather than who performs the action.','["It is shorter","It is always grammatically required","To focus on the process/object rather than who performs the action.","It is more informal"]','Passive future = impersonal/objective academic style.','hard'),
  (cid,12,84,'gap_fill','The policy ___ (implement/passive) gradually over a three-year period.','will be implemented',NULL,'Future passive for policy/institutional action.','medium'),

  -- BLOCK 13: will vs may/might (certainty vs possibility)
  (cid,13,85,'multiple_choice','Which sentence expresses a CERTAIN future outcome?','If emissions continue, temperatures will rise by 3°C by 2100.','["If emissions continue, temperatures might rise by 3°C by 2100.","If emissions continue, temperatures could rise by 3°C by 2100.","If emissions continue, temperatures will rise by 3°C by 2100.","If emissions continue, temperatures may rise by 3°C by 2100."]','"Will rise" = certain prediction. "May/might/could" = possible but uncertain.','medium'),
  (cid,13,86,'gap_fill','The treatment ___ (may/reduce) side effects in some patients, but further trials are needed.','may reduce / might reduce',NULL,'"May/might reduce" for uncertain, hedged prediction.','medium'),
  (cid,13,87,'multiple_choice','Rank these from MOST to LEAST certain about the future: "will / might / may / could"','will > may ≈ might ≈ could','["will > may > might > could","will > could > may > might","may > will > might > could","will > may ≈ might ≈ could"]','Will = ~100% certain. May/might/could all express possibility (~30-60%).','hard'),
  (cid,13,88,'gap_fill','The technology ___ (revolutionize) healthcare within the next decade — early trials are highly promising.','will',NULL,'Strong prediction with supporting evidence → will.','medium'),
  (cid,13,89,'multiple_choice','Which sentence is MOST appropriate for a TOEFL essay making a hedged prediction?','Investment in early education may yield significant long-term economic benefits.','["Investment in early education will definitely yield benefits.","Investment in early education might possibly perhaps yield some benefits.","Investment in early education may yield significant long-term economic benefits.","Investment in early education is yielding benefits."]','"May yield" = appropriately hedged future prediction for academic writing.','hard'),
  (cid,13,90,'gap_fill','While will is used for certainty, ___ and ___ are used for possibility in future predictions.','may / might',NULL,'"May" and "might" for uncertain future possibilities.','easy'),

  -- BLOCK 14: shall (formal suggestions/academic) + other future forms review
  (cid,14,91,'gap_fill','___ (shall) we proceed to the next section of the experiment? (formal suggestion)','Shall',NULL,'"Shall" for formal first-person suggestions/offers in British English.','hard'),
  (cid,14,92,'multiple_choice','In formal academic/legal writing, "shall" is used to express:','A formal obligation or requirement.','["A prediction based on evidence","A formal obligation or requirement.","A spontaneous offer","A past habit"]','"Shall" in formal documents = obligatory requirement (e.g., "Participants shall complete all sections").','hard'),
  (cid,14,93,'gap_fill','In the formal contract, it states: "All data ___ (shall/be) stored securely for a minimum of five years."','shall be',NULL,'"Shall be + past participle" = formal future passive obligation.','hard'),
  (cid,14,94,'multiple_choice','Which sentence uses the future tense MOST appropriately for a TOEFL academic essay?','The long-term consequences of this policy will likely become apparent within the next decade.','["The long-term consequences of this policy are going to become apparent next decade.","Long-term consequences will definitively occur in the next decade.","The long-term consequences of this policy will likely become apparent within the next decade.","Long-term consequences: they will be apparent next decade for sure."]','"Will likely become apparent" = future with modal hedge (likely) for academic writing.','hard'),
  (cid,14,95,'gap_fill','This research ___ (will/hope/contribute) to our understanding of the mechanism.','will hopefully contribute / will contribute',NULL,'"Will hopefully contribute" = future with evaluative adverb (hedged optimism).','medium'),
  (cid,14,96,'multiple_choice','Which future expression is most common in academic writing for conclusions?','This study will contribute to future research by establishing a baseline.','["I''m going to write more in the future.","This study will contribute to future research by establishing a baseline.","We''ll probably do more research.","There''s going to be more to study."]','"Will + infinitive" for academic conclusions and contributions.','medium'),

  -- BLOCK 15: TOEFL Reading
  (cid,15,97,'multiple_choice','[TOEFL Reading] "If current trends continue, renewable energy will account for over 60% of global power by 2040." The use of "will" suggests:','A strong, evidence-based prediction about the future.','["This is a scientific fact already proven","This is a personal opinion","A strong, evidence-based prediction about the future.","A possible but unlikely scenario"]','"Will account for" = confident future prediction based on current trajectory.','medium'),
  (cid,15,98,'gap_fill','[TOEFL Reading] "The findings ___ (challenge) existing theories about memory consolidation." Best modal for a strong academic prediction?','will',NULL,'"Will challenge" = confident predicted outcome of the research.','easy'),
  (cid,15,99,'multiple_choice','[TOEFL Reading] "Once this phase of testing is complete, the drug will enter clinical trials." The time clause "once this phase is complete" uses:','Present simple because time clauses cannot use will for future reference.','["Future passive (will be completed)","Present perfect passive (has been completed)","Present simple because time clauses cannot use will for future reference.","Past simple because the phase is already underway"]','"Once + present simple" = rule for time clauses with future meaning.','hard'),
  (cid,15,100,'gap_fill','[TOEFL Reading] "These measures, if implemented, ___ (significant/reduce) carbon emissions within five years." Best form?','will significantly reduce',NULL,'Conditional first: if + present → will + base verb for predicted outcome.','medium'),
  (cid,15,101,'multiple_choice','[TOEFL Reading] A passage predicts "cities will be redesigned around pedestrian zones within 20 years." A student paraphrases this as "cities may be redesigned." Is this accurate?','No — the original uses will (certainty); may implies less certainty.','["Yes — they both express future events","No — the original uses will (certainty); may implies less certainty.","Yes — will and may are interchangeable in predictions","No — the original uses present simple"]','Will = strong prediction. May = only a possibility.','hard'),

  -- BLOCK 16: TOEFL Listening
  (cid,16,102,'multiple_choice','[TOEFL Listening] A professor says: "By the end of this semester, you will have completed a full research cycle." What tense is used?','Future perfect (will have + past participle).','["Future simple","Present perfect","Future perfect (will have + past participle).","Past perfect"]','"Will have completed" = future perfect: completed by a future deadline.','hard'),
  (cid,16,103,'gap_fill','[TOEFL Listening] "Results from the ongoing trial ___ (announce/passive) at the annual conference next spring." Best form?','will be announced',NULL,'Future passive: will be + past participle.','easy'),
  (cid,16,104,'multiple_choice','[TOEFL Listening] A professor says "Scientists will not fully understand this process until more research is done." The time clause uses:','Present simple (not will) — time clauses don''t take will.','["Future simple (will be done)","Past perfect","Present simple (not will) — time clauses don''t take will.","Present continuous"]','"Until more research is done" = present passive in time clause.','hard'),

  -- BLOCK 17: TOEFL Speaking
  (cid,17,105,'production','[TOEFL Speaking — 45s] You have read about the impact of AI on employment. Predict both positive and negative changes in the next decade using will and may/might. Include at least one future passive.','',NULL,'AI will transform the job market significantly over the next decade. Many routine positions will be automated, which may cause short-term unemployment. However, new industries will emerge that do not yet exist. Jobs in AI maintenance and ethical oversight will be created. Workers who adapt may benefit enormously from increased productivity.','hard'),
  (cid,17,106,'production','[TOEFL Speaking — 45s] Describe what will happen in your field of study or work over the next 20 years. Use will for strong predictions and may/might for less certain ones. Include one future passive and one time clause.','',NULL,'Medicine will be revolutionized by precision genomics. As soon as gene editing becomes affordable, it will be applied to prevent hereditary diseases. Diagnoses may be made by AI algorithms with greater accuracy than human physicians. Drug development will be accelerated significantly. Healthcare costs might decrease as preventive medicine becomes widespread.','hard'),

  -- BLOCK 18: TOEFL Writing
  (cid,18,107,'production','[TOEFL Writing] Write a 5-sentence paragraph predicting the future of education using: will (×2), will be + passive (×1), may/might (×1), and a time clause with present simple (×1).','',NULL,'Education will shift significantly toward personalized, AI-driven learning models. Once digital infrastructure reaches remote communities, millions of children will gain access to world-class teaching. Traditional classroom settings may give way to hybrid or fully virtual environments. Standardized testing will be replaced by continuous competency-based assessments. Teachers will continue to play a crucial role, but their function will evolve from content delivery to mentorship and facilitation.','hard'),
  (cid,18,108,'production','[TOEFL Writing — Error Correction] Fix all future tense errors: "When the results will arrive, we will analyze them. The study will complete next year. As soon as funding will be approved, we will start. Participants won''t informed until April."','',NULL,'When the results arrive (remove will); will be completed (passive); As soon as funding is approved; won''t be informed (passive: won''t + be + past participle).','hard'),
  (cid,18,109,'production','[TOEFL Writing — 150 words] Write a paragraph on the topic "How will climate change affect urban planning in the next 50 years?" Use at least 5 different future structures: will + base verb, will be + past participle (passive), may/might, time clause (once/when + present), and will likely + base verb.','',NULL,'Urban planning will be fundamentally reimagined over the next 50 years as climate change intensifies. Coastal cities will likely relocate critical infrastructure away from flood-prone zones. Once sea walls and elevated road systems are built, existing neighborhoods may be retrofitted for increased resilience. Green roofs and urban forests will be integrated into building codes to manage heat island effects. When extreme weather events become more frequent, emergency response infrastructure will be upgraded significantly. Some cities may adopt bold net-zero carbon plans that restrict car use entirely. Overall, the cities of 2075 will look and function very differently from those of today.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
